test_suite:
test('functions do not run synchronously', () => {
  const q = new MicrotaskQueue();
  const fn = vi.fn();
  q.add(fn);
  expect(fn).not.toHaveBeenCalled();
});

test('functions run after microtask', async () => {
  const q = new MicrotaskQueue();
  const results = [];
  q.add(() => results.push(1));
  q.add(() => results.push(2));
  await Promise.resolve();
  expect(results).toEqual([1, 2]);
});

test('all fns in same flush are called', async () => {
  const q = new MicrotaskQueue();
  const fn1 = vi.fn();
  const fn2 = vi.fn();
  q.add(fn1);
  q.add(fn2);
  await Promise.resolve();
  expect(fn1).toHaveBeenCalledTimes(1);
  expect(fn2).toHaveBeenCalledTimes(1);
});

// __hidden__
test('fns added after flush run in next microtask', async () => {
  const q = new MicrotaskQueue();
  const results = [];
  q.add(() => results.push('first'));
  await Promise.resolve();
  q.add(() => results.push('second'));
  await Promise.resolve();
  expect(results).toEqual(['first', 'second']);
});

solution:
export class MicrotaskQueue {
  constructor() {
    this.queue = [];
    this.scheduled = false;
  }
  add(fn) {
    this.queue.push(fn);
    if (!this.scheduled) {
      this.scheduled = true;
      queueMicrotask(() => {
        this.scheduled = false;
        const toRun = this.queue.splice(0);
        toRun.forEach(f => f());
      });
    }
  }
}
